package ratelimit

import (
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(t time.Time) *fakeClock { return &fakeClock{t: t} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	base := time.Unix(0, 0)
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 10, 1, nil, true},
		{"zero capacity", 0, 1, newFakeClock(base), true},
		{"negative capacity", -1, 1, newFakeClock(base), true},
		{"zero rate", 10, 0, newFakeClock(base), true},
		{"negative rate", 10, -1, newFakeClock(base), true},
		{"valid", 10, 2, newFakeClock(base), false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error, got nil")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket, got nil")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	cases := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"initial allow", 5, 1, 0, 1, true},
		{"zero n always allowed", 5, 1, 0, 0, true},
		{"negative n always allowed", 5, 1, 0, -2, true},
		{"exceeds capacity", 5, 1, 0, 6, false},
		{"refill after advance", 5, 2, time.Second, 3, true},
		{"drain then refill", 5, 1, 0, 5, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock(base)
			b, err := New(tc.cap, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			clk.Advance(tc.advance)
			if got := b.AllowN(tc.n); got != tc.want {
				t.Fatalf("AllowN(%d) = %v, want %v", tc.n, got, tc.want)
			}
		})
	}
}

func TestRefillExact(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(10, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	if !b.AllowN(10) {
		t.Fatal("expected initial drain to succeed")
	}
	if b.AllowN(1) {
		t.Fatal("expected empty bucket to reject")
	}
	clk.Advance(5 * time.Second)
	if !b.AllowN(5) {
		t.Fatal("expected 5 refilled tokens")
	}
	if b.AllowN(1) {
		t.Fatal("expected only 5 tokens available")
	}
}

func TestConcurrentAllow(t *testing.T) {
	clk := newFakeClock(time.Unix(0, 0))
	b, err := New(100, 1, clk)
	if err != nil {
		t.Fatal(err)
	}
	var allowed atomic.Int32
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.Allow() {
				allowed.Add(1)
			}
		}()
	}
	wg.Wait()
	if got := allowed.Load(); got != 100 {
		t.Fatalf("allowed = %d, want 100", got)
	}
}
