func TestNewValidation(t *testing.T) {
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, newFakeClock(), true},
		{"negative capacity", -1, 1, newFakeClock(), true},
		{"zero rate", 1, 0, newFakeClock(), true},
		{"negative rate", 1, -1, newFakeClock(), true},
		{"valid", 2, 1.5, newFakeClock(), false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b, err := New(tt.capacity, tt.rate, tt.clock)
			if (err != nil) != tt.wantErr {
				t.Fatalf("New() error = %v, wantErr %v", err, tt.wantErr)
			}
			if !tt.wantErr && b == nil {
				t.Fatal("New() returned nil bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	tests := []struct {
		name    string
		cap     int
		rate    float64
		advance time.Duration
		n       int
		want    bool
	}{
		{"zero n always allowed", 1, 1, 0, 0, true},
		{"negative n always allowed", 1, 1, 0, -1, true},
		{"within capacity", 2, 1, 0, 2, true},
		{"above capacity", 2, 1, 0, 3, false},
		{"refill before allow", 2, 1, 1500 * time.Millisecond, 1, true},
		{"insufficient after refill", 2, 1, 500 * time.Millisecond, 2, false},
